auto [t0, t1] = knot::get_domain(4, 4, k);
bool t0_close = std::fabs(t0 - 5.0) < 1e-10;
bool t1_close = std::fabs(t1 - 10.0) < 1e-10;

// uncomment #include "knot.h"

// Reverse knot vector
auto k = knot::make_clamped_uniform(4, 4, 1.0);
